cat > test_branch_with_call.json << 'EOF'
{
  "defs": {
    "AddMark": { "steps":[
      {"op":"map","as":"marked","expr":"value + params.offset"}
    ]}
  },
  "pipeline": {
    "steps": [
      {
        "op":"branch",
        "branches":[
          {
            "when":"value > 50",
            "steps":[
              {"op":"call","name":"AddMark","params":{"offset":1000}}
            ]
          },
          {
            "when":"otherwise",
            "steps":[
              {"op":"map","as":"marked","expr":"value"}
            ]
          }
        ]
      },
      {"op":"select","columns":["id","marked"]}
    ]
  },
  "dataset":[
    {"id":1,"value":30},
    {"id":2,"value":60}
  ]
}
EOF
python etl_pipeline.py --execute true < test_branch_with_call.json

